        dut.dmem.mem[1006] = 32'h3F300303;
        dut.dmem.mem[1007] = 32'hBE1D2779;
        dut.dmem.mem[1008] = 32'h3ECA1B2B;
        dut.dmem.mem[1009] = 32'h3BB1F8D4;
        dut.dmem.mem[1010] = 32'hBE32BFA6;
        dut.dmem.mem[1011] = 32'hBF103A54;
        dut.dmem.mem[1012] = 32'h3E045E81;
        dut.dmem.mem[1013] = 32'h3F1440AF;
