        dut.dmem.mem[1022] = 32'h3E58DA72;
        dut.dmem.mem[1023] = 32'h3EB8645E;
        reset = 0;

        while (!halted && cycle_count < max_cycles) begin
            @(posedge clk);
            cycle_count = cycle_count + 1;
        end

        if (!halted) begin
            $display("FAIL: core never halted within %0d cycles", max_cycles);
            errors = errors + 1;
        end else begin
            $display("Halted after %0d cycles. tohost=%0d", cycle_count, tohost_value);
            check(tohost_value, 32'd3, "tohost (n7 = traps taken)");
            check(dut.n_bank.regs[6], 32'd3, "n6 (causes 0+0+3: 2 ILLEGAL, 1 PRIV)");
            check(dut.dmem.mem[192], 32'h3F800000, "P of square 0x400 (+1.000000)");
            check(dut.dmem.mem[193], 32'hBE15F4B2, "P of square 0x600 (-0.146441)");
            check(dut.dmem.mem[194], 32'hBE15F4B2, "P of square 0x800 (-0.146441)");
            check(dut.dmem.mem[195], 32'h3F7D628B, "P of square 0xA00 (+0.989785)");
            check(dut.dmem.mem[196], 32'h3F800000, "P of square 0xEE0 (+1.000000)");
            check(n_lat, 8, "PLAQ instructions seen");
            check(lat[0], 913, "cycles of legal PLAQ #0");
            check(lat[1], 913, "cycles of legal PLAQ #1");
            check(lat[2], 913, "cycles of legal PLAQ #2");
            check(lat[3], 913, "cycles of legal PLAQ #3");
            check(lat[4], 913, "cycles of legal PLAQ #4");
            check(lat[5], 1, "cycles of trapping PLAQ #0");
            check(lat[6], 1, "cycles of trapping PLAQ #1");
            check(lat[7], 1, "cycles of trapping PLAQ #2");
        end

        if (errors == 0) $display("ALL AXISA PLAQ TESTS PASSED");
        else $display("%0d AXISA PLAQ TEST(S) FAILED", errors);
        $finish;
    end
